// Gather queued statewide rows (APN-only) and build ONE BatchData
// property-lookup body of up to 100 requests, each keyed by APN + county
// (+ city/town for RI disambiguation). options.skipTrace=true asks BatchData to
// append owner phone/email in the same call. Keep `rows` so results map back by id.
const items = $input.all();
let rows = [];
if (items.length === 1 && Array.isArray(items[0].json)) rows = items[0].json;
else rows = items.map(i => i.json);
rows = rows.filter(r => r && r.id && r.apn);
if (rows.length === 0) { return [{ json: { count: 0, requests: [], rows: [] } }]; }
const requests = rows.map(r => {
  const address = { state: String(r.state || 'RI').trim() };
  if (r.county) address.county = String(r.county).trim();
  if (r.city)   address.city   = String(r.city).trim();   // RI: town = municipality, helps disambiguate
  return { address, apn: String(r.apn).trim() };
});
return [{ json: { count: rows.length, requests, rows } }];

// Map BatchData property-lookup results back to the queued rows.
// The exact response nesting for /property/lookup/sync is confirmed on the first
// real batch — this parser is defensive: it matches by normalized APN first, then
// falls back to positional order (we send one request per row, in order).
// If a field nests differently live, adjust pickName/pickMailing/pickPhones/pickEmails
// below; the full record is always saved to skiptrace_raw for inspection.
const resp = $input.first().json || {};
const rows = ($('Build Lookup Request').first().json.rows) || [];
const results = resp.results || resp;
let props = results.properties || results.property || results.lookups || resp.properties || [];
if (!Array.isArray(props)) props = props ? [props] : [];
const norm = s => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
function apnOf(p){ return p.apn || p.APN || p.parcelNumber || (p.ids && p.ids.apn) || (p.assessment && p.assessment.apn) || (p.parcel && p.parcel.apn) || ''; }
function ownerOf(p){ return p.owner || (p.assessment && p.assessment.owner) || (p.deed && p.deed.owner) || {}; }
function pickName(p){ const o = ownerOf(p); const n = o.name || o.fullName || {}; if (typeof n === 'string') return n; return n.full || [n.first, n.last].filter(Boolean).join(' ') || o.ownerName || [o.firstName, o.lastName].filter(Boolean).join(' ') || p.ownerName || null; }
function pickMailing(p){ const o = ownerOf(p); return o.mailingAddress || o.mailing || p.mailingAddress || p.mailing || {}; }
function personsOf(p){ const o = ownerOf(p); return p.persons || (p.skipTrace && p.skipTrace.persons) || o.persons || (p.contact && p.contact.persons) || []; }
function pickPhones(p){ let out = []; for (const person of personsOf(p)) { const arr = person.phoneNumbers || person.phones || []; (Array.isArray(arr)?arr:[arr]).forEach(x => { const v = (x && (x.number || x.phone || x.phoneNumber)) || (typeof x === 'string' ? x : null); if (v) out.push(v); }); } return out; }
function pickEmails(p){ let out = []; for (const person of personsOf(p)) { const arr = person.emails || person.emailAddresses || []; (Array.isArray(arr)?arr:[arr]).forEach(x => { const v = (x && (x.email || x.address)) || (typeof x === 'string' ? x : null); if (v) out.push(v); }); } return out; }
const byApn = {};
props.forEach((p, idx) => { const k = norm(apnOf(p)); if (k) (byApn[k] = byApn[k] || []).push(p); p.__idx = idx; });
const nowIso = new Date().toISOString();
return rows.map((r, i) => {
  let p = (byApn[norm(r.apn)] || [])[0];
  if (!p && props.length === rows.length) p = props[i]; // positional fallback
  if (!p) { return { json: { id: r.id, status: 'no_match', skiptraced_at: nowIso } }; }
  const name = pickName(p); const m = pickMailing(p); const phones = pickPhones(p); const emails = pickEmails(p);
  const matched = !!(name || m.street || phones.length || emails.length);
  return { json: {
    id: r.id, status: matched ? 'traced' : 'no_match', skiptraced_at: nowIso,
    owner_name: name || null,
    owner_phone: phones[0] || null,
    owner_phone2: phones[1] || null,
    owner_email: emails[0] || null,
    owner_mailing_street: m.street || null,
    owner_mailing_city: m.city || null,
    owner_mailing_state: m.state || null,
    owner_mailing_zip: m.zip || m.postalCode || null,
    skiptrace_raw: p
  } };
});
